// SPEC RS84: renders the ranking eval cases (web/evals.json, generated by ops/build_evals_page.py) on evals.html.
// A separate file because the CSP allows no inline script (RS49). Text is set with textContent only.
"use strict";
(function(){
  function el(tag, cls, text){ var e=document.createElement(tag); if(cls) e.className=cls; if(text!=null) e.textContent=String(text); return e; }
  function kstars(n){ return n>=1000 ? (n/1000).toFixed(n>=10000?0:1)+"k" : String(n); }
  function meta(label, value){ var p=el("p","ev-meta"); p.appendChild(el("span",null,label+": ")); p.appendChild(document.createTextNode(value)); return p; }
  function fitCase(c){ var li=el("li","ev-case");
    li.appendChild(el("h3",null,c.name)); li.appendChild(el("p","ev-goal",c.goal));
    li.appendChild(meta("Candidates", c.candidates.map(function(x){
      return x.name+" (best-match position "+x.position+", "+kstars(x.stars)+" stars, "+x.licence+(x.starter?", starter":"")+")"; }).join("; ")));
    if(c.prefer_starters) li.appendChild(meta("Mode","starting from scratch (starters preferred)"));
    var p=meta("Must rank first", c.expect_top); li.appendChild(p);
    return li; }
  function hybridCase(c){ var li=el("li","ev-case");
    li.appendChild(el("h3",null,c.name)); li.appendChild(el("p","ev-goal",c.goal));
    li.appendChild(meta("Description", c.description ? c.description : "(empty)"));
    li.appendChild(meta("Fit order in", c.rows.join(", ")));
    if(c.meaning_scores) li.appendChild(meta("Meaning scores", c.meaning_scores.join(", ")));
    li.appendChild(meta("Expected ("+c.expect+")", c.expect_order.join(", ")));
    return li; }
  function fill(id, cases, make){ var ul=document.getElementById(id); if(!ul) return;
    cases.forEach(function(c){ ul.appendChild(make(c)); }); }
  fetch("/evals.json",{headers:{"Accept":"application/json"}}).then(function(r){ if(!r.ok) throw new Error(r.status); return r.json(); })
    .then(function(d){ fill("fitCases", d.fit.cases, fitCase); fill("hybridCases", d.hybrid.cases, hybridCase);
      var lead=document.getElementById("fitLead");
      if(lead) lead.textContent="Relevance, popularity and licence freedom together. "+d.fit.cases.length+" goal cases; all of them must pass ("+
        Math.round(d.fit.threshold*100)+"% pass bar).";
    })
    .catch(function(){ var e=document.getElementById("evalsErr"); if(e) e.hidden=false; });
})();
